"""Actual Web Audio clock, independent key release, overwrite boundaries and loop cleanup."""
import argparse,json
from pathlib import Path
from playwright.sync_api import sync_playwright
p=argparse.ArgumentParser();p.add_argument('--output',required=True,type=Path);p.add_argument('--url');a=p.parse_args();a.output.mkdir(parents=True,exist_ok=False);root=Path(__file__).resolve().parents[1]
with sync_playwright() as pw:
 b=pw.chromium.launch(channel='msedge',headless=True);page=b.new_page(viewport={'width':1375,'height':884},reduced_motion='reduce');errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(a.url or (root/'SkyMusicStudio_Standalone.html').as_uri());page.locator('#newSongBtn').click();page.locator('#createTitle').fill('录制验收');page.locator('#createConfirm').click()
 def setup():page.evaluate('''()=>{const w=window.SKY_MUSIC_TEST,c=w.Music.blank();c.lengthTicks=7680;const track=c.tracks[0].id;c.notes=[{id:'long',trackId:track,pitch:48,startTick:0,durationTicks:1920,soundTicks:1920,gate:1,velocity:85}];w.mw.project.composition=c;w.mw.track=track;w.mw.selected.clear();w.mw.cursor=480;w.MusicAudio.position=250;w.musicRender()}''')
 setup();page.locator('#musicRecordMode').select_option('free');page.locator('#musicWriteMode').select_option('overwrite');page.locator('#musicMetronome').check();page.locator('#musicRecord').click();page.wait_for_function('window.SKY_MUSIC_TEST.mw.recording!==null');page.locator('#musicRollViewport').focus();page.keyboard.down('q');page.wait_for_timeout(150);page.keyboard.down('e');page.wait_for_timeout(50);page.keyboard.up('q');page.wait_for_timeout(250);page.keyboard.up('e');page.locator('#musicRecord').click()
 result=page.evaluate('window.SKY_MUSIC_TEST.mw.project.composition.notes');performance=[n for n in result if 'performance' in n];assert len(performance)==2,result;assert abs(performance[0]['performance']['durationMs']-performance[1]['performance']['durationMs'])>30,performance;assert any(n['pitch']==48 and n['startTick']==0 and n['durationTicks']==480 for n in result);assert any(n['pitch']==48 and n['startTick']>480 for n in result)
 assert page.evaluate('window.SKY_MUSIC_TEST.MusicAudio.voices.size')==0;page.locator('#musicUndo').click();assert page.evaluate('window.SKY_MUSIC_TEST.mw.project.composition.notes.length')==1
 setup();page.locator('#musicRecordMode').select_option('quantized');page.locator('#musicWriteMode').select_option('insert');page.locator('#musicRecord').click();page.wait_for_function('window.SKY_MUSIC_TEST.mw.recording!==null');page.locator('#musicRollViewport').focus();page.wait_for_timeout(70);page.keyboard.down('q');page.wait_for_timeout(90);page.keyboard.up('q');page.locator('#musicRecord').click();quantized=page.evaluate('window.SKY_MUSIC_TEST.mw.project.composition.notes.find(n=>n.performance)');assert abs(quantized['startTick']/480-round(quantized['startTick']/480))<1e-7,quantized
 # Real audio uses independent track banks. Mute/solo filters scheduling, ties merge voices.
 domain=page.evaluate('''async()=>{const w=window.SKY_MUSIC_TEST,M=w.Music,c=M.blank(),a=c.tracks[0].id;c.tracks.push({id:'harp',name:'竖琴',instrument:'offline-harp',volume:.5,mute:false,solo:false});c.notes=[{id:'a',trackId:a,pitch:60,startTick:0,durationTicks:960,soundTicks:960,gate:1,velocity:85,tieNext:'b'},{id:'b',trackId:a,pitch:60,startTick:960,durationTicks:960,soundTicks:960,gate:1,velocity:85},{id:'h',trackId:'harp',pitch:64,startTick:0,durationTicks:3840,soundTicks:3840,gate:1,velocity:50}];const events=M.compile(c);if(events.length!==2||events.find(e=>e.id==='a').durationMs!==1000)throw Error('tie voices');c.tracks[1].mute=true;if(M.compile(c).length!==1)throw Error('mute');c.tracks[1].mute=false;c.tracks[1].solo=true;if(M.compile(c)[0].id!=='h')throw Error('solo');c.tracks[1].solo=false;w.mw.project.composition=c;w.mw.track=a;w.mw.cursor=0;w.musicRender();await w.MusicAudio.prepare(c);return {banks:w.MusicAudio.banks.size,tiedDuration:events[0].durationMs}}''');assert domain['banks']>=2
 page.locator('#musicLoopStart').fill('1');page.locator('#musicLoopEnd').fill('2');page.locator('#musicLoop').check();page.locator('#musicPlay').click();page.wait_for_function('window.SKY_MUSIC_TEST.MusicAudio.playing');page.wait_for_timeout(2300);assert page.evaluate('window.SKY_MUSIC_TEST.MusicAudio.playing');assert page.evaluate('window.SKY_MUSIC_TEST.MusicAudio.now()')<2000;page.locator('#musicPlay').click();assert page.evaluate('window.SKY_MUSIC_TEST.MusicAudio.voices.size')==0
 page.screenshot(path=str(a.output/'recording.png'));assert not errors,errors;b.close()
(a.output/'results.json').write_text(json.dumps({'passed':True,'freeNotes':performance,'quantized':quantized,'audio':domain,'errors':errors},indent=2),'utf-8');print('PASS real recording, independent release, overwrite boundaries, undo, multitrack banks, loop and voice cleanup')
